FILE Bounds.dfy
module Bounds {
  export provides Ready, MakeReady, ExposeReady
  opaque predicate Ready(x: int) { 0 <= x <= 10 }

  lemma MakeReady(x: int)
    requires 0 <= x <= 10
    ensures Ready(x)
  { reveal Ready(); }

  lemma ExposeReady(x: int)
    requires Ready(x)
    ensures 0 <= x <= 10
  { reveal Ready(); }
}

FILE Client.dfy
include "Bounds.dfy"
include "Transform.dfy"
module Client {
  import B = Bounds
  import T = Transform
  lemma Progress(x: int)
    requires 0 <= x <= 10
    ensures T.Shift(x) > x
  {
  }
}

FILE Transform.dfy
include "Bounds.dfy"
module Transform {
  import B = Bounds
  export provides B, Shift, EvaluateShift
  opaque function Shift(x: int): int {
    if 0 <= x <= 10 then x + 1 else 0
  }

  lemma EvaluateShift(x: int)
    requires B.Ready(x)
    ensures Shift(x) == x + 1
  {
    B.ExposeReady(x);
    reveal Shift();
  }
}

